27	QEMU_PLUGIN_EXPORT int qemu_plugin_version = QEMU_PLUGIN_VERSION;
28	
29	typedef struct {
30	    struct qemu_plugin_register *gpr[32];
31	    struct qemu_plugin_register *fpr[32];
32	    struct qemu_plugin_register *fcsr;  // L20: frm[7:5] | fflags[4:0]
33	    struct qemu_plugin_register *pc;
34	    struct qemu_plugin_register *priv;  // L6: gdbstub virtual feature
35	
36	    // M-mode CSRs as exposed by QEMU's gdbstub csr feature.
37	    struct qemu_plugin_register *mstatus;
38	    struct qemu_plugin_register *mepc;
39	    struct qemu_plugin_register *mtvec;
40	    struct qemu_plugin_register *mcause;
41	    struct qemu_plugin_register *mtval;
42	    struct qemu_plugin_register *mscratch;
43	    struct qemu_plugin_register *medeleg;
44	    struct qemu_plugin_register *mideleg;
45	    struct qemu_plugin_register *mip;
46	    struct qemu_plugin_register *mie;
47	    struct qemu_plugin_register *mcycle;
48	    struct qemu_plugin_register *minstret;
49	    struct qemu_plugin_register *satp;
50	
51	    // Andes custom machine setup CSRs (crt0 writes these at boot). mcache_ctl
52	    // enables the L1 caches; without transporting it the cycle engine resumes
53	    // with caches off. Absent on non-Andes stubs -> NULL handle -> drains 0.
54	    struct qemu_plugin_register *mcache_ctl;
55	    struct qemu_plugin_register *mmisc_ctl;
56	
57	    struct qemu_plugin_register *pmpcfg[HYBRID_PMP_CFG_NUM];
58	    struct qemu_plugin_register *pmpaddr[HYBRID_PMP_ADDR_NUM];
59	
60	    struct qemu_plugin_register *vstart;
61	    struct qemu_plugin_register *vxsat;
62	    struct qemu_plugin_register *vxrm;
63	    struct qemu_plugin_register *vcsr;
64	    struct qemu_plugin_register *vtype;
65	    struct qemu_plugin_register *vl;
66	    struct qemu_plugin_register *vlenb;
67	    struct qemu_plugin_register *vreg[32];
68	
69	    // icount-trigger mode: per-vcpu retired-insn counter, incremented in
70	    // on_icount_tick. When icount_target is reached, the same drain path
71	    // as CSR/PC mode fires (on_handoff -> write_state_atomic -> exit 200).
72	    uint64_t icount_retired;
73	} VcpuRegs;
