206	// Lazily resolves register handles. The plugin's vcpu_init runs before
207	// QEMU has registered the dynamic gdb coprocessors (FPU, virtual, csr,
208	// vector), so qemu_plugin_get_registers() returns only the 33 core CPU
209	// regs at that moment. By the time the entry trigger fires, all dynamic
210	// features are registered and a fresh call returns the full list.
211	static void resolve_handles(VcpuRegs *v)
212	{
213	    g_autoptr(GArray) regs = qemu_plugin_get_registers();
214	    for (int i = 0; i < 32; i++) {
215	        v->gpr[i] = find_reg(regs, hybrid_gpr_names[i]);
216	        v->fpr[i] = find_reg(regs, hybrid_fpr_names[i]);
217	    }
218	    v->fcsr = find_reg(regs, "fcsr");
219	    v->pc = find_reg(regs, "pc");
220	    v->priv = find_reg(regs, "priv");
221	
222	    v->mstatus  = find_reg(regs, "mstatus");
223	    v->mepc     = find_reg(regs, "mepc");
224	    v->mtvec    = find_reg(regs, "mtvec");
225	    v->mcause   = find_reg(regs, "mcause");
226	    v->mtval    = find_reg(regs, "mtval");
227	    v->mscratch = find_reg(regs, "mscratch");
228	    v->medeleg  = find_reg(regs, "medeleg");
229	    v->mideleg  = find_reg(regs, "mideleg");
230	    v->mip      = find_reg(regs, "mip");
231	    v->mie      = find_reg(regs, "mie");
232	    v->mcycle   = find_reg(regs, "mcycle");
233	    v->minstret = find_reg(regs, "minstret");
234	    v->satp     = find_reg(regs, "satp");
235	
236	    v->mcache_ctl = find_reg(regs, "mcache_ctl");
237	    v->mmisc_ctl  = find_reg(regs, "mmisc_ctl");
238	
239	    char buf[16];
240	    for (int i = 0; i < HYBRID_PMP_CFG_NUM; i++) {
241	        g_snprintf(buf, sizeof(buf), "pmpcfg%d", i);
242	        v->pmpcfg[i] = find_reg(regs, buf);
243	    }
244	    for (int i = 0; i < HYBRID_PMP_ADDR_NUM; i++) {
245	        g_snprintf(buf, sizeof(buf), "pmpaddr%d", i);
246	        v->pmpaddr[i] = find_reg(regs, buf);
247	    }
248	
249	    v->vstart = find_reg(regs, "vstart");
250	    v->vxsat  = find_reg(regs, "vxsat");
251	    v->vxrm   = find_reg(regs, "vxrm");
252	    v->vcsr   = find_reg(regs, "vcsr");
253	    v->vtype  = find_reg(regs, "vtype");
254	    v->vl     = find_reg(regs, "vl");
255	    v->vlenb  = find_reg(regs, "vlenb");
256	    for (int i = 0; i < 32; i++) {
257	        g_snprintf(buf, sizeof(buf), "v%d", i);
258	        v->vreg[i] = find_reg(regs, buf);
259	    }
260	}
