288	// Atomic on POSIX: write to a mkstemp-reserved tmp file, fsync, rename.
289	// mkstemp guarantees uniqueness via a 6-char random suffix + atomic
290	// O_EXCL-style inode reservation, so concurrent plugin instances cannot
291	// collide even under aggressive PID reuse (B13). The tmp lives in the
292	// same directory as `path` so the rename is intra-filesystem.
293	static int write_state_atomic(const struct hybrid_state_v1 *s, const char *path)
294	{
295	    char tmp[PATH_MAX];
296	    int n = g_snprintf(tmp, sizeof(tmp), "%s.tmp.XXXXXX", path);
297	    if (n < 0 || (size_t) n >= sizeof(tmp)) {
298	        fprintf(stderr, "hybrid_handoff: tmp path too long\n");
299	        return -1;
300	    }
301	    int fd = g_mkstemp(tmp);
302	    if (fd < 0) {
303	        perror("hybrid_handoff: g_mkstemp");
304	        return -1;
305	    }
306	    // g_mkstemp creates the file 0600; no further chmod needed.
307	    ssize_t want = (ssize_t) sizeof(*s);
308	    ssize_t got = write(fd, s, sizeof(*s));
309	    if (got != want) {
310	        perror("hybrid_handoff: write");
311	        close(fd);
312	        unlink(tmp);
313	        return -1;
314	    }
315	    fsync(fd);
316	    close(fd);
317	    if (rename(tmp, path) != 0) {
318	        perror("hybrid_handoff: rename");
319	        unlink(tmp);
320	        return -1;
321	    }
322	    return 0;
323	}
