325	// Append one record to a `.ckpts` stream (concatenated hybrid_state_v1,
326	// cosim_redesign F3). No tmp-rename dance: the stream has a single writer
327	// and readers only run after the producer exits.
328	static int append_state_stream(const struct hybrid_state_v1 *s,
329	                               const char *path)
330	{
331	    FILE *f = fopen(path, "ab");
332	    if (!f) {
333	        perror("hybrid_handoff: fopen stream");
334	        return -1;
335	    }
336	    const size_t n = fwrite(s, 1, sizeof(*s), f);
337	    fclose(f);
338	    return n == sizeof(*s) ? 0 : -1;
339	}
