341	// Drain CPU state into `*s`. pc is computed by the caller (from a
342	// HandoffSite for trigger paths, or 0 for the atexit path which lacks an
343	// insn context). If minstret_override is non-zero, it replaces QEMU's PMU
344	// minstret (used by drain_at_exit mode to record a plugin-counted
345	// retired-insn total).
346	static void drain_state_into(unsigned int vcpu_idx, uint64_t pc,
347	                             uint64_t minstret_override,
348	                             struct hybrid_state_v1 *sp)
349	{
350	    VcpuRegs *v = qemu_plugin_scoreboard_find(vcpu_state, vcpu_idx);
351	    resolve_handles(v);
352	    memset(sp, 0, sizeof(*sp));
353	    struct hybrid_state_v1 s = {0};
354	    s.magic   = HYBRID_STATE_MAGIC;
355	    s.version = HYBRID_STATE_VERSION;
356	    s.flags   = HYBRID_FLAG_RV64;
357	    s.hart_id = vcpu_idx;
358	    // L6: real privilege at the boundary; M-mode fallback only when the
359	    // stub doesn't advertise the gdbstub virtual feature (a missing handle
360	    // reads as 0 = U, which would silently demote the hart).
361	    s.priv    = v->priv ? (read_reg64(v->priv) & 0x3) : 3;
362	    s.pc      = pc;
363	    for (int i = 0; i < 32; i++) s.gpr[i] = read_reg64(v->gpr[i]);
364	
365	    // Floating-point: only set FP flag if at least one handle was bound,
366	    // i.e. QEMU advertised the FPU feature (D extension).
367	    int has_fp = 0;
368	    for (int i = 0; i < 32; i++) {
369	        s.fpr[i] = read_reg64(v->fpr[i]);
370	        if (v->fpr[i]) has_fp = 1;
371	    }
372	    if (has_fp) s.flags |= HYBRID_FLAG_FP;
373	    s.fcsr = read_reg64(v->fcsr);  // L20: rides HYBRID_FLAG_FP
374	
375	    s.mstatus  = read_reg64(v->mstatus);
376	    s.mepc     = read_reg64(v->mepc);
377	    s.mtvec    = read_reg64(v->mtvec);
378	    s.mcause   = read_reg64(v->mcause);
379	    s.mtval    = read_reg64(v->mtval);
380	    s.mscratch = read_reg64(v->mscratch);
381	    s.medeleg  = read_reg64(v->medeleg);
382	    s.mideleg  = read_reg64(v->mideleg);
383	    s.mip      = read_reg64(v->mip);
384	    s.mie      = read_reg64(v->mie);
385	    s.mcycle   = read_reg64(v->mcycle);
386	    s.minstret = minstret_override ? minstret_override
387	                                   : read_reg64(v->minstret);
388	    s.satp     = read_reg64(v->satp);
389	
390	    // Andes cache fix: carry crt0's cache-enable so the cycle engine resumes
391	    // with caches on (NULL handle on a non-Andes stub reads back as 0).
392	    s.mcache_ctl = read_reg64(v->mcache_ctl);
393	    s.mmisc_ctl  = read_reg64(v->mmisc_ctl);
394	
395	    for (int i = 0; i < HYBRID_PMP_CFG_NUM; i++)
396	        s.pmpcfg[i] = read_reg64(v->pmpcfg[i]);
397	    for (int i = 0; i < HYBRID_PMP_ADDR_NUM; i++)
398	        s.pmpaddr[i] = read_reg64(v->pmpaddr[i]);
399	
400	    // Vector: only set V flag if QEMU advertised the V extension. vlenb
401	    // bounds the per-register byte count copied into vreg[]. The policy
402	    // helper (hybrid_v_drain_policy) decides SKIP/OK/ABORT from the
403	    // handle truthiness so we don't conflate "stub missing vlenb" with
404	    // "V disabled at runtime"; see include/hybrid/v_drain_policy.h.
405	    s.vstart = read_reg64(v->vstart);
406	    s.vxsat  = read_reg64(v->vxsat);
407	    s.vxrm   = read_reg64(v->vxrm);
408	    s.vcsr   = read_reg64(v->vcsr);
409	    s.vtype  = read_reg64(v->vtype);
410	    s.vl     = read_reg64(v->vl);
411	    s.vlenb  = read_reg64(v->vlenb);
412	    int has_other_v = (v->vstart || v->vxsat || v->vxrm || v->vcsr
413	                       || v->vtype || v->vl);
414	    if (!has_other_v) {
415	        for (int i = 0; i < 32; i++)
416	            if (v->vreg[i]) { has_other_v = 1; break; }
417	    }
418	    HybridVDrainPolicy vpol = hybrid_v_drain_policy(
419	        v->vlenb != NULL, has_other_v, s.vlenb);
420	    if (vpol == HYBRID_V_DRAIN_ABORT) {
421	        if (v->vlenb == NULL)
422	            fprintf(stderr,
423	                    "hybrid_handoff: stub advertised V CSRs/regs but not "
424	                    "vlenb; refusing to drain partial V state\n");
425	        else
426	            fprintf(stderr,
427	                    "hybrid_handoff: vlenb=%" PRIu64 " exceeds the wire-format "
428	                    "ceiling HYBRID_VLEN_BYTES_MAX=%d (VLEN %d); refusing to "
429	                    "truncate V registers\n",
430	                    s.vlenb, HYBRID_VLEN_BYTES_MAX,
431	                    8 * HYBRID_VLEN_BYTES_MAX);
432	        exit(2);
433	    }
434	    if (vpol == HYBRID_V_DRAIN_OK) {
435	        s.flags |= HYBRID_FLAG_V;
436	        /* The policy guarantees vlenb <= HYBRID_VLEN_BYTES_MAX here, so the
437	         * full live register fits the wire-format slot -- no clamp (L11). */
438	        for (int i = 0; i < 32; i++)
439	            (void) read_reg_bytes(v->vreg[i],
440	                                  &s.vreg[(size_t) i * HYBRID_VLEN_BYTES_MAX],
441	                                  (size_t) s.vlenb);
442	    }
443	
444	    *sp = s;
445	}
