447	// Drain CPU state to `path`. Does NOT call exit -- caller decides exit(200)
448	// (normal trigger) vs _exit(200) (inside atexit chain).
449	static void drain_state_to_file(unsigned int vcpu_idx, uint64_t pc,
450	                                uint64_t minstret_override, const char *path)
451	{
452	    struct hybrid_state_v1 s;
453	    drain_state_into(vcpu_idx, pc, minstret_override, &s);
454	    if (write_state_atomic(&s, path) != 0) {
455	        fprintf(stderr, "hybrid_handoff: failed to write state file\n");
456	        exit(2);
457	    }
458	    fprintf(stderr,
459	            "hybrid_handoff: drained state to %s (pc=%#" PRIx64 ")\n",
460	            path, s.pc);
461	}
