463	// Shared drain tail: capture the (pre-execution) state, report `resume_pc`
464	// as the vsim resume point, and exit 200.
465	static void handoff_drain(unsigned int vcpu_idx, uint64_t resume_pc)
466	{
467	    // F14: suppress the atexit drain path now that we have a real trigger.
468	    drained_already = 1;
469	    drain_state_to_file(vcpu_idx, resume_pc, 0, outfile_path);
470	    // 200 == kExitHandoffToQemu in verilator/src/hybrid/exit_codes.hpp.
471	    // Distinguishes drain from workload completion (0) so the orchestrator
472	    // can decide the next spawn.
473	    exit(200);
474	}
