476	// Marker sites. The marker is an architectural NOP, so the pre-execution
477	// state equals the post-retire state and the window resumes AFTER it
478	// (vaddr+size, computed at translation time; reading the gdbstub PC inside
479	// the exec callback can lag the actual current insn when V instructions
480	// retire just before the trigger -- TCG defers PC writes for performance).
481	static void on_handoff(unsigned int vcpu_idx, void *udata)
482	{
483	    const HandoffSite *site = (const HandoffSite *) udata;
484	    if (site->kind != HYBRID_HANDOFF_ENTER) return;
485	    handoff_drain(vcpu_idx, compute_handoff_pc(site));
486	}
487	
488	// pc/icount/slice boundary sites. Exec callbacks fire BEFORE the insn
489	// executes, and the boundary insn is real user code (unlike a marker NOP):
490	// the drained state must resume AT the boundary so the insn executes inside
491	// the vsim window rather than on neither leg. (Skipping it corrupts the
492	// window's architectural state -- e.g. a skipped vsetivli leaves vtype.vill
493	// set and the first vector op of the window faults.)
494	static void on_handoff_boundary(unsigned int vcpu_idx, void *udata)
495	{
496	    const HandoffSite *site = (const HandoffSite *) udata;
497	    if (site->kind != HYBRID_HANDOFF_ENTER) return;
498	    handoff_drain(vcpu_idx, site->vaddr);
499	}
