501	// F14: per-insn tick. Increments a global counter every retired insn so the
502	// drain-at-exit path can report a true retired-insn total (independent of
503	// QEMU's PMU semantics).
504	static void on_count_tick(unsigned int vcpu_idx, void *udata)
505	{
506	    (void) vcpu_idx;
507	    (void) udata;
508	    atexit_insn_count++;
509	}
510	
511	// F14: atexit drain. Fires when QEMU exits naturally (no ROI trigger). The
512	// record is a CONTEXT-FREE count, not an architectural drain: depending on
513	// the guest's exit path this callback runs on the vCPU thread (semihosting
514	// EXIT) or on QEMU's main loop thread (vplat/SimControl shutdown request),
515	// and on the main thread there is no vCPU context -- any
516	// qemu_plugin_read_register aborts QEMU (api.c asserts current_cpu). The
517	// only consumer (the SimPoint estimate profile) reads minstret = the
518	// plugin-side retire counter (N_total); pc=0 is the positive marker that
519	// the atexit path drained (no trigger). If any other trigger already
520	// drained, return immediately (drained_already guards against double
521	// drain). Inside an atexit handler, exit() is UB per C11 7.22.4.4; use
522	// _exit() to skip the rest of the atexit chain.
523	static void on_atexit(qemu_plugin_id_t id, void *udata)
524	{
525	    (void) id;
526	    (void) udata;
527	    if (drained_already) return;
528	    if (!drain_at_exit_mode) return;
529	    struct hybrid_state_v1 s = {0};
530	    s.magic    = HYBRID_STATE_MAGIC;
531	    s.version  = HYBRID_STATE_VERSION;
532	    s.flags    = HYBRID_FLAG_RV64;
533	    s.priv     = 3;
534	    s.minstret = atexit_insn_count;
535	    if (write_state_atomic(&s, outfile_path) != 0)
536	        fprintf(stderr, "hybrid_handoff: failed to write state file\n");
537	    else
538	        fprintf(stderr,
539	                "hybrid_handoff: drained exit count record to %s "
540	                "(minstret=%" PRIu64 ")\n",
541	                outfile_path, s.minstret);
542	    fflush(stderr);
543	    _exit(200);
544	}
545	
546	// Per-insn tick for oracle exit-drain mode. udata is this insn's HandoffSite.
547	// When armed (the exit boundary's own tick ran), this tick fires before its
548	// insn executes, so a drain here records the post-retire state of the
549	// boundary insn with pc = the dynamically-next insn's vaddr.
550	static void on_oracle_tick(unsigned int vcpu_idx, void *udata)
551	{
552	    const HandoffSite *site = (const HandoffSite *) udata;
553	    if (oracle_armed
554	        && (!drain_pc_set || site->vaddr == drain_pc_arg)) {
555	        handoff_drain(vcpu_idx, site->vaddr);
556	    }
557	    if (exit_pc_mode ? (site->vaddr == exit_pc_arg)
558	                     : (site->kind == HYBRID_HANDOFF_EXIT)) {
559	        oracle_armed = 1;
560	    }
561	}
562	
563	// Checkpoint drain for cosim mode: append to the <outfile>.ckpts stream and
564	// KEEP RUNNING (no exit, drained_already untouched -- the final count uses
565	// handoff_drain).
566	static void cosim_checkpoint_drain(unsigned int vcpu_idx, uint64_t pc,
567	                                   size_t k)
568	{
569	    g_autofree char *path = g_strdup_printf("%s.ckpts", outfile_path);
570	    struct hybrid_state_v1 s;
571	    drain_state_into(vcpu_idx, pc, 0, &s);
572	    if (append_state_stream(&s, path) != 0) {
573	        fprintf(stderr, "hybrid_handoff: failed to append checkpoint %zu\n",
574	                k);
575	        exit(2);
576	    }
577	    fprintf(stderr,
578	            "hybrid_handoff: checkpoint %zu appended to %s (pc=%#" PRIx64
579	            ")\n", k, path, s.pc);
580	}
581	
582	// Per-insn tick for cosim mode. udata is this insn's HandoffSite. Exec
583	// callbacks fire pre-execution: at an armed tick, `cosim_done` post-entry
584	// insns have retired and the current insn has not, so draining when
585	// cosim_done == target captures "entry + target retires" with pc = the
586	// dynamically-next insn's vaddr -- the same point as the vsim checkpoint's
587	// DPC at minstret delta == target.
588	static void on_cosim_tick(unsigned int vcpu_idx, void *udata)
589	{
590	    const HandoffSite *site = (const HandoffSite *) udata;
591	    if (!cosim_armed) {
592	        if (cosim_pc_mode ? (site->vaddr == cosim_pc_arg)
593	                          : (site->kind == HYBRID_HANDOFF_ENTER)) {
594	            cosim_armed = 1;
595	            // Marker mode: the marker is counted by neither side -- done.
596	            // pc mode: the boundary insn retires inside the window (the
597	            // handoff resumes AT it) -- fall through and count this tick.
598	            if (!cosim_pc_mode) return;
599	        } else {
600	            return;
601	        }
602	    }
603	    if (cosim_idx < cosim_n_counts && cosim_done == cosim_counts[cosim_idx]) {
604	        if (cosim_idx + 1 == cosim_n_counts)
605	            handoff_drain(vcpu_idx, site->vaddr);  // final: exits 200
606	        else
607	            cosim_checkpoint_drain(vcpu_idx, site->vaddr, cosim_idx + 1);
608	        cosim_idx++;
609	    }
610	    cosim_done++;
611	}
612	
613	// Per-insn tick for lock-step oracle mode. udata is this insn's
614	// HandoffSite. Drains BEFORE the insn executes (record k = state before
615	// attempt k+1) and appends to the outfile stream.
616	static void on_lockstep_tick(unsigned int vcpu_idx, void *udata)
617	{
618	    const HandoffSite *site = (const HandoffSite *) udata;
619	    if (!lockstep_armed) {
620	        if (site->vaddr != lockstep_pc_arg) return;
621	        lockstep_armed = 1;
622	    }
623	    struct hybrid_state_v1 s;
624	    drain_state_into(vcpu_idx, site->vaddr, 0, &s);
625	    if (append_state_stream(&s, outfile_path) != 0) {
626	        fprintf(stderr, "hybrid_handoff: failed to append lockstep record "
627	                "%" PRIu64 "\n", lockstep_count);
628	        exit(2);
629	    }
630	    lockstep_count++;
631	    if (lockstep_max != 0 && lockstep_count >= lockstep_max) {
632	        drained_already = 1;
633	        fprintf(stderr,
634	                "hybrid_handoff: lockstep done, %" PRIu64 " record(s) in "
635	                "%s\n", lockstep_count, outfile_path);
636	        fflush(stderr);
637	        exit(200);
638	    }
639	}
640	
641	// Per-insn tick for icount mode. udata is the per-insn HandoffSite
642	// pre-allocated at translation time, so on_handoff's compute_handoff_pc
643	// returns the lag-free post-trigger PC (same property as the CSR path).
644	static void on_icount_tick(unsigned int vcpu_idx, void *udata)
645	{
646	    VcpuRegs *v = qemu_plugin_scoreboard_find(vcpu_state, vcpu_idx);
647	    if (++v->icount_retired < icount_target) return;
648	    on_handoff_boundary(vcpu_idx, udata);
649	}
650	
651	// Per-insn tick for BBV-emit mode. udata is the bb_id (1-based) cast to
652	// pointer; that mapping is stable across calls because bbv_emit_assign_id
653	// is hashed by TB-start PC. The tick attributes one insn to the bb_id and
654	// flushes a slice row when the per-slice counter saturates.
655	static void on_bbv_tick(unsigned int vcpu_idx, void *udata)
656	{
657	    (void) vcpu_idx;
658	    uint64_t bb_id = (uint64_t) GPOINTER_TO_UINT(udata);
659	    bbv_emit_tick(bbv_emit, bb_id);
660	}
661	
662	// Per-insn tick for slice-consume mode (F11). Counts insns into the
663	// slice accumulator; on each slice boundary increments slice_consume_idx
664	// and resets the accumulator. Once slice_consume_idx exceeds the target
665	// slice index, drains via on_handoff at that same insn boundary. udata
666	// is the per-insn HandoffSite (allocated at translation time) so the
667	// post-trigger PC reaches on_handoff lag-free.
668	static void on_slice_consume_tick(unsigned int vcpu_idx, void *udata)
669	{
670	    if (++slice_consume_acc < bbv_slice_target) return;
671	    slice_consume_acc = 0;
672	    if (slice_consume_idx++ < slice_at_target) return;
673	    // After the post-increment above, slice_consume_idx == slice_at_target+1
674	    // (the count of fully retired slices). Log so the e2e test can verify
675	    // drain timing without relying on minstret (which is a cycle-counter
676	    // proxy on andes-ax45mpv and does not track plugin-counted insns).
677	    fprintf(stderr,
678	            "hybrid_handoff: slice-consume drain (idx=%" PRIu64
679	            " target=%" PRIu64 ")\n",
680	            slice_consume_idx, slice_at_target);
681	    on_handoff_boundary(vcpu_idx, udata);
682	}
683	
684	static void vcpu_tb_trans(qemu_plugin_id_t id, struct qemu_plugin_tb *tb)
685	{
686	    (void) id;
687	    size_t n = qemu_plugin_tb_n_insns(tb);
688	
689	    // BBV-mode: assign a stable bb_id to this TB (1-based, hashed by
690	    // TB-start vaddr). Same id is shared by every insn in the TB.
691	    uint64_t bb_id = 0;
692	    if (bbv_mode && n > 0) {
693	        uint64_t tb_pc = qemu_plugin_insn_vaddr(qemu_plugin_tb_get_insn(tb, 0));
694	        bb_id = bbv_emit_assign_id(bbv_emit, tb_pc);
695	    }
696	
697	    for (size_t i = 0; i < n; i++) {
698	        struct qemu_plugin_insn *insn = qemu_plugin_tb_get_insn(tb, i);
699	
700	        // Oracle exit-drain mode: exclusive with every other mode (enforced
701	        // at install), so it owns the insn's registration outright. The site
702	        // carries the marker kind so the tick can arm on the EXIT marker.
703	        if (exit_marker_mode || exit_pc_mode) {
704	            HandoffSite *site = g_new0(HandoffSite, 1);
705	            site->kind  = HYBRID_HANDOFF_NONE;
706	            site->vaddr = qemu_plugin_insn_vaddr(insn);
707	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
708	            if (exit_marker_mode && site->size == 4) {
709	                uint32_t raw = 0;
710	                if (qemu_plugin_insn_data(insn, &raw, sizeof(raw)) == sizeof(raw))
711	                    hybrid_match_handoff_insn(raw, &site->kind);
712	            }
713	            qemu_plugin_register_vcpu_insn_exec_cb(
714	                insn, on_oracle_tick, QEMU_PLUGIN_CB_R_REGS, site);
715	            continue;
716	        }
717	
718	        // Cosim oracle mode: exclusive with every other mode (enforced at
719	        // install). Same site shape as the exit oracle; kind carries the
720	        // marker match so the tick can arm on the ENTER marker.
721	        if (cosim_marker_mode || cosim_pc_mode) {
722	            HandoffSite *site = g_new0(HandoffSite, 1);
723	            site->kind  = HYBRID_HANDOFF_NONE;
724	            site->vaddr = qemu_plugin_insn_vaddr(insn);
725	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
726	            if (cosim_marker_mode && site->size == 4) {
727	                uint32_t raw = 0;
728	                if (qemu_plugin_insn_data(insn, &raw, sizeof(raw)) == sizeof(raw))
729	                    hybrid_match_handoff_insn(raw, &site->kind);
730	            }
731	            qemu_plugin_register_vcpu_insn_exec_cb(
732	                insn, on_cosim_tick, QEMU_PLUGIN_CB_R_REGS, site);
733	            continue;
734	        }
735	
736	        // Lock-step oracle mode: exclusive with every other mode (enforced
737	        // at install). Every insn ticks; the tick arms at lockstep_pc.
738	        if (lockstep_pc_mode) {
739	            HandoffSite *site = g_new0(HandoffSite, 1);
740	            site->kind  = HYBRID_HANDOFF_NONE;
741	            site->vaddr = qemu_plugin_insn_vaddr(insn);
742	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
743	            qemu_plugin_register_vcpu_insn_exec_cb(
744	                insn, on_lockstep_tick, QEMU_PLUGIN_CB_R_REGS, site);
745	            continue;
746	        }
747	
748	        // F14 count tick: registered FIRST so the count is incremented
749	        // before any trigger callback can call exit(200). NO_REGS keeps
750	        // the per-insn cost minimal (a single uint64 add).
751	        if (drain_at_exit_mode) {
752	            qemu_plugin_register_vcpu_insn_exec_cb(
753	                insn, on_count_tick, QEMU_PLUGIN_CB_NO_REGS, NULL);
754	        }
755	
756	        // BBV callback is registered BEFORE icount so that if both modes
757	        // fire on the same insn (icount target == slice multiple), the
758	        // slice row is emitted before exit(200) is called.
759	        if (bbv_mode) {
760	            qemu_plugin_register_vcpu_insn_exec_cb(
761	                insn, on_bbv_tick, QEMU_PLUGIN_CB_NO_REGS,
762	                GUINT_TO_POINTER((guint) bb_id));
763	        }
764	
765	        // Slice-consume callback (F11). Registered after BBV so a BBV
766	        // row at the same boundary is flushed first; ordering vs icount
767	        // is irrelevant (both drain).
768	        if (slice_consume_mode) {
769	            HandoffSite *site = g_new0(HandoffSite, 1);
770	            site->kind  = HYBRID_HANDOFF_ENTER;
771	            site->vaddr = qemu_plugin_insn_vaddr(insn);
772	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
773	            qemu_plugin_register_vcpu_insn_exec_cb(
774	                insn, on_slice_consume_tick, QEMU_PLUGIN_CB_R_REGS, site);
775	        }
776	
777	        if (icount_mode) {
778	            HandoffSite *site = g_new0(HandoffSite, 1);
779	            site->kind  = HYBRID_HANDOFF_ENTER;
780	            site->vaddr = qemu_plugin_insn_vaddr(insn);
781	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
782	            qemu_plugin_register_vcpu_insn_exec_cb(
783	                insn, on_icount_tick, QEMU_PLUGIN_CB_R_REGS, site);
784	        }
785	
786	        if (pc_mode) {
787	            // PC-trigger mode: vaddr-only match; the drain resumes AT the
788	            // boundary (on_handoff_boundary), so the insn size is recorded
789	            // only for completeness.
790	            if (qemu_plugin_insn_vaddr(insn) != enter_pc_arg) continue;
791	            HandoffSite *site = g_new0(HandoffSite, 1);
792	            site->kind  = HYBRID_HANDOFF_ENTER;
793	            site->vaddr = qemu_plugin_insn_vaddr(insn);
794	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
795	            qemu_plugin_register_vcpu_insn_exec_cb(
796	                insn, on_handoff_boundary, QEMU_PLUGIN_CB_R_REGS, site);
797	            continue;
798	        }
799	
800	        // Marker-trigger mode (default).
801	        // The markers are `slti x0, x0, 0x5A0/0x5A1`, always 32-bit
802	        // (sz==4): SLTI has no compressed form, so the sz!=4 skip is
803	        // exact, not an approximation.
804	        size_t sz = qemu_plugin_insn_size(insn);
805	        if (sz != 4) continue;
806	        uint32_t raw = 0;
807	        if (qemu_plugin_insn_data(insn, &raw, sizeof(raw)) != sizeof(raw))
808	            continue;
809	        hybrid_handoff_kind kind = HYBRID_HANDOFF_NONE;
810	        if (!hybrid_match_handoff_insn(raw, &kind)) continue;
811	        HandoffSite *site = g_new0(HandoffSite, 1);
812	        site->kind  = kind;
813	        site->vaddr = qemu_plugin_insn_vaddr(insn);
814	        site->size  = (uint32_t) sz;
815	        qemu_plugin_register_vcpu_insn_exec_cb(
816	            insn, on_handoff, QEMU_PLUGIN_CB_R_REGS, site);
817	    }
818	}
